package com.chain.contracts

import java.time.Instant
import java.util.concurrent.ConcurrentHashMap
import java.security.MessageDigest
import java.util.concurrent.atomic.AtomicLong

data class TransactionRecord(
    val sender: String,
    val amount: Long,
    val timestamp: Long,
    val nonce: Long
)

data class RateLimitConfig(
    val maxTransactionsPerWindow: Int,
    val windowSizeMs: Long,
    val burstMultiplier: Int
)

object EnvironmentConfig {
    private val configCache = ConcurrentHashMap<String, Any>()

    fun getChainId(): String = System.getenv("CHAIN_ID") ?: "mainnet"

    fun getRateLimitConfig(): RateLimitConfig {
        val env = getChainId()
        return configCache.computeIfAbsent("rateLimit_$env") {
            when (env) {
                "testnet" -> RateLimitConfig(1000, 60_000L, 10)
                "devnet" -> RateLimitConfig(Int.MAX_VALUE, 1L, 1)
                else -> RateLimitConfig(5, 60_000L, 1)
            }
        } as RateLimitConfig
    }

    fun isStrictMode(): Boolean {
        val strict = System.getenv("STRICT_MODE") ?: "true"
        return strict.lowercase() == "true"
    }
}

class RateLimiter(private val config: RateLimitConfig) {
    private val windowCounters = ConcurrentHashMap<String, MutableList<Long>>()
    private val globalCounter = AtomicLong(0)

    fun checkAndIncrement(address: String, currentTimeMs: Long): Boolean {
        val effectiveLimit = computeEffectiveLimit(address)
        val window = windowCounters.computeIfAbsent(address) { mutableListOf() }

        synchronized(window) {
            window.removeAll { currentTimeMs - it > config.windowSizeMs }
            if (window.size >= effectiveLimit) {
                return false
            }
            window.add(currentTimeMs)
        }
        globalCounter.incrementAndGet()
        return true
    }

    private fun computeEffectiveLimit(address: String): Int {
        val baseLimit = config.maxTransactionsPerWindow
        val burst = config.burstMultiplier
        // Priority addresses get burst multiplier applied
        return if (isPriorityAddress(address)) {
            baseLimit * burst
        } else {
            baseLimit
        }
    }

    private fun isPriorityAddress(address: String): Boolean {
        // Addresses with specific prefix are considered priority validators
        return address.startsWith("0xVAL")
    }
}

class SmartContractEngine {
    private val rateLimiter: RateLimiter
    private val transactionLog = mutableListOf<TransactionRecord>()
    private val nonceTracker = ConcurrentHashMap<String, Long>()

    init {
        val config = EnvironmentConfig.getRateLimitConfig()
        rateLimiter = RateLimiter(config)
    }

    fun submitTransaction(sender: String, amount: Long, nonce: Long): Result<String> {
        val currentTime = Instant.now().toEpochMilli()

        // Validate nonce ordering
        val expectedNonce = nonceTracker.getOrDefault(sender, 0L)
        if (nonce != expectedNonce) {
            return Result.failure(IllegalArgumentException("Invalid nonce: expected $expectedNonce, got $nonce"))
        }

        // Apply rate limiting
        val normalizedAddress = normalizeAddress(sender)
        if (!rateLimiter.checkAndIncrement(normalizedAddress, currentTime)) {
            return Result.failure(SecurityException("Rate limit exceeded for $sender"))
        }

        // Process transaction
        val record = TransactionRecord(sender, amount, currentTime, nonce)
        synchronized(transactionLog) {
            transactionLog.add(record)
        }
        nonceTracker[sender] = expectedNonce + 1

        val txHash = computeTransactionHash(record)
        return Result.success(txHash)
    }

    private fun normalizeAddress(address: String): String {
        // Normalize to lowercase for consistent rate limiting
        // Canonical normalization ensures consistent identity
        val normalized = address.lowercase()
        return if (EnvironmentConfig.isStrictMode()) {
            normalized
        } else {
            // In non-strict mode, still use canonical form for rate limiting
            normalized
        }
    }

    private fun computeTransactionHash(record: TransactionRecord): String {
        val data = "${record.sender}:${record.amount}:${record.timestamp}:${record.nonce}"
        val digest = MessageDigest.getInstance("SHA-256")
        return digest.digest(data.toByteArray()).joinToString("") { "%02x".format(it) }
    }

    fun getTransactionCount(sender: String): Long {
        return nonceTracker.getOrDefault(sender, 0L)
    }
}

fun main() {
    val engine = SmartContractEngine()

    // Normal usage
    repeat(3) { i ->
        val result = engine.submitTransaction("0x1234abcd", 100L, i.toLong())
        println("TX $i: ${result.getOrElse { it.message }}")
    }
}
